### Benchmark on causalAssembly production-line data (Goebler et al., 2024).
### One task = one sample (station, regime, k, rep) of n rows generated by
### ca-sample.R: regime "dag" samples the station's induced DAG (true graph:
### induced DAG; DAG mode, PC baseline and warm start), regime "admg" samples
### the station and its ancestors and keeps the station (true graph: latent
### projection of the full line onto the station; ADMG mode, FCI baseline and
### warm start). Partial-correlation tests up to k on the data, PC/FCI by
### gaussCItest on cor(data), GLIP with the encodings in GLIP_ENCODINGS.
### Metrics against the true graph's representation computed for
### conditioning sets up to k (SEP on the tested statements, SHD of the
### CPDAG/PAG), loss of the warm start and of each fit.
### Environment: CA_DIR (gt_full.csv, stations.json), CA_DATA (samples).
rr_task_ca <- function(task, out) {
  mode <- if (task$regime == "dag") "dag" else "admg"
  ms <- task$ms
  alpha <- task$alpha
  dir <- file.path(out, task$id)
  ca_dir <- Sys.getenv("CA_DIR", file.path(rr_root(), "results", "causal-assembly"))
  data_dir <- Sys.getenv("CA_DATA", file.path(rr_root(), "inst", "results", "ca-2026-11", "data"))
  input <- rr_cached(file.path(dir, "input.rds"), {
    data <- readRDS(file.path(data_dir, sprintf("%s-%s-r%02d.rds", task$station, task$regime, task$rep)))
    data <- as.data.frame(scale(data))
    V <- colnames(data)
    A <- as.matrix(utils::read.csv(file.path(ca_dir, "gt_full.csv"), row.names = 1, check.names = FALSE))
    A <- 1 * (A != 0)
    gt <- if (mode == "dag") A[V, V] else marginalize_dag_to_admg(A, V)
    tests <- learn_graph(
      data = data, max_size = ms, mode = mode,
      test_args = list(reg_YonZ = "lrm", reg_XonZ = "lrm"),
      return_tests_only = TRUE, comets = FALSE, test = "gaussCItest"
    )
    otests <- .compute_oracle_tests(gt, ms, mode)
    suff <- list(C = stats::cor(data), n = nrow(data))
    t0 <- Sys.time()
    pc <- as(pcalg::pc(suff, pcalg::gaussCItest, labels = V, alpha = alpha)@graph, "matrix")
    base <- if (mode == "dag") {
      pc
    } else {
      as(pcalg::fciPlus(suff, pcalg::gaussCItest,
        labels = V, alpha = alpha, selectionBias = FALSE, verbose = FALSE
      )@amat, "matrix")
    }
    t_base <- as.numeric(Sys.time() - t0, units = "secs")
    list(V = V, gt = gt, tests = tests, otests = otests, base = base, pc = pc, t_base = t_base)
  })
  if (inherits(input, "rr_error")) stop(input$error)
  V <- input$V
  d <- length(V)
  if (mode == "dag") {
    start <- .ess_to_dag(input$base)
    hints <- 1 * (start != 0)
    baseline <- "PC"
  } else {
    start <- tryCatch(.pag_to_admg(input$base), error = function(e) {
      .to_admg(.ess_to_dag(input$pc)) # as in exp-simulation.R
    })
    hints <- 1 * (input$base != 0)
    baseline <- "FCI"
  }
  ### CPDAG/PAG (computed with d - 2, as in exp-simulation.R: the helper
  ### returns NULL for max_size < d - 2); SEP on the tested statements
  ORACLE <- .compute_graphical_representation(input$gt, d - 2, mode)
  decision <- 1 * (input$tests$p.value > alpha)
  loss_of <- function(g) sum(.compute_oracle_tests(g, ms, mode)$p.value != decision)

  fits <- list()
  for (enc in task$encodings) {
    fits[[paste0("GLIP-", enc)]] <- rr_cached(file.path(dir, paste0("GLIP-", enc, ".rds")), {
      f <- rr_glip(enc, mode, input$tests, d, ms, V, alpha, task$walltime, start, hints)
      list(graph = f$graph, dcon = f$tests$dcon, info = rr_solver_info(f), time = f$optim$runtime)
    })
  }
  fits[[baseline]] <- list(graph = start, time = input$t_base)
  start_loss <- loss_of(start)

  res <- lapply(names(fits), \(method) {
    f <- fits[[method]]
    err <- if (inherits(f, "rr_error")) f$error else NA
    learned <- NULL
    pp <- NULL
    if (is.na(err) && !is.null(f$graph)) {
      learned <- .compute_graphical_representation(f$graph, d - 2, mode)
      ### separations of the graph itself on the tested statements, for every
      ### method alike (1 = separated, the scale of otests$p.value)
      pp <- .compute_oracle_tests(f$graph, ms, mode)$p.value
    }
    met <- rr_metrics(learned, ORACLE, mode, ms, input$otests, precomputed_predicted = pp)
    info <- if (!is.null(f$info)) f$info else rr_solver_info(list(optim = list()))
    data.frame(
      exp = "ca", method = method, met,
      loss = if (is.null(pp)) NA else sum(pp != decision), start_loss = start_loss,
      input_sep = mean(decision != input$otests$p.value), ntests = length(decision),
      time = if (is.null(f$time)) NA else f$time, info, error = err,
      station = task$station, regime = task$regime, d = d, ms = ms, n = task$n,
      mode = mode, iter = task$rep, walltime = task$walltime, alpha = alpha
    )
  }) |> do.call("rbind", args = _)
  res
}
